package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain attempts to order the given dominoes into a chain such that
// adjacent halves match and the two open ends also match.
// It returns the chain and whether such a chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)

	// Empty input produces an empty (valid) chain.
	if n == 0 {
		return []Domino{}, true
	}

	// A single domino can only form a closed chain if both halves match.
	if n == 1 {
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	used := make([]bool, n)
	chain := make([]Domino, n)

	var backtrack func(pos int) bool
	backtrack = func(pos int) bool {
		if pos == n {
			// All dominoes placed; check that the open ends match.
			return chain[0][0] == chain[n-1][1]
		}
		// The value that the next domino must match on its left side.
		match := chain[pos-1][1]
		for i := 0; i < n; i++ {
			if used[i] {
				continue
			}
			d := input[i]
			// Try the domino as-is.
			if d[0] == match {
				used[i] = true
				chain[pos] = d
				if backtrack(pos + 1) {
					return true
				}
				used[i] = false
			}
			// Try the domino flipped.
			if d[1] == match && d[0] != d[1] {
				used[i] = true
				chain[pos] = Domino{d[1], d[0]}
				if backtrack(pos + 1) {
					return true
				}
				used[i] = false
			}
		}
		return false
	}

	// Try each domino (and orientation) as the starting stone.
	for i := 0; i < n; i++ {
		d := input[i]
		used[i] = true
		chain[0] = d
		if backtrack(1) {
			return chain, true
		}
		used[i] = false

		if d[0] != d[1] {
			used[i] = true
			chain[0] = Domino{d[1], d[0]}
			if backtrack(1) {
				return chain, true
			}
			used[i] = false
		}
	}
	return nil, false
}
```

